// win: slot names legitimately repeat (14 pages), the insert loop writes EVERY
// instance, and last-write-wins made the verdict depend on slice order.
func visibleIncomingBySlot(sections []SectionData) map[string]int {
	m := make(map[string]int, len(sections))
	for _, s := range sections {
		m[s.ComponentName] += visibleTextLength(s.HTML)
	}
	return m
}

